CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_seed_dummy_funcionario_500`()
BEGIN

    DECLARE v_i INT DEFAULT 1;

    START TRANSACTION;

    WHILE v_i <= 500 DO

        INSERT INTO funcionario
        (
            nome,
            ativo,
            criado_em
        )
        VALUES
        (
            CONCAT('FUNCIONARIO_SEED_', v_i),
            1,
            NOW(6)
        )
        ON DUPLICATE KEY UPDATE
            nome = VALUES(nome);

        SET v_i = v_i + 1;

    END WHILE;

    COMMIT;

END ;;
